func matchParameterized(message string) (string, int32, bool) {
	if message == "" {
		return "", 0, false
	}
	switch message[0] {
	case '2':
		if argument, ok := matchDecimalPattern(message, "2FA_CONFIRM_WAIT_", ""); ok {
			return Err2FAConfirmWait, argument, true
		}
	case 'A':
		if argument, ok := matchDecimalPattern(message, "ALLOW_PAYMENT_REQUIRED_", ""); ok {
			return ErrAllowPaymentRequired, argument, true
		}
		if argument, ok := matchDecimalPattern(message, "AUTH_RESTART_", ""); ok {
			return ErrAuthRestart, argument, true
		}
	case 'E':
		if argument, ok := matchDecimalPattern(message, "EMAIL_UNCONFIRMED_", ""); ok {
			return ErrEmailUnconfirmed, argument, true
		}
	case 'F':
		if argument, ok := matchDecimalPattern(message, "FILE_MIGRATE_", ""); ok {
			return ErrFileMigrate, argument, true
		}
		if argument, ok := matchDecimalPattern(message, "FILE_PART_", "_MISSING"); ok {
			return ErrFilePartMissing, argument, true
		}
		if argument, ok := matchDecimalPattern(message, "FILE_REFERENCE_", "_EMPTY"); ok {
			return ErrFileReferenceEmpty, argument, true
		}
		if argument, ok := matchDecimalPattern(message, "FILE_REFERENCE_", "_EXPIRED"); ok {
			return ErrFileReferenceExpired, argument, true
		}
		if argument, ok := matchDecimalPattern(message, "FILE_REFERENCE_", "_INVALID"); ok {
			return ErrFileReferenceInvalid, argument, true
		}
		if argument, ok := matchDecimalPattern(message, "FLOOD_PREMIUM_WAIT_", ""); ok {
			return ErrFloodPremiumWait, argument, true
		}
		if argument, ok := matchDecimalPattern(message, "FLOOD_TEST_PHONE_WAIT_", ""); ok {
			return ErrFloodTestPhoneWait, argument, true
		}
		if argument, ok := matchDecimalPattern(message, "FLOOD_WAIT_", ""); ok {
			return ErrFloodWait, argument, true
		}
	case 'I':
		if argument, ok := matchDecimalPattern(message, "INTERDC_", "_CALL_ERROR"); ok {
			return ErrInterDCCallError, argument, true
		}
		if argument, ok := matchDecimalPattern(message, "INTERDC_", "_CALL_RICH_ERROR"); ok {
			return ErrInterDCCallRichError, argument, true
		}
	case 'N':
		if argument, ok := matchDecimalPattern(message, "NETWORK_MIGRATE_", ""); ok {
			return ErrNetworkMigrate, argument, true
		}
	case 'P':
		if argument, ok := matchDecimalPattern(message, "PASSWORD_TOO_FRESH_", ""); ok {
			return ErrPasswordTooFresh, argument, true
		}
		if argument, ok := matchDecimalPattern(message, "PHONE_MIGRATE_", ""); ok {
			return ErrPhoneMigrate, argument, true
		}
		if argument, ok := matchDecimalPattern(message, "PREMIUM_SUB_ACTIVE_UNTIL_", ""); ok {
			return ErrPremiumSubActiveUntil, argument, true
		}
		if argument, ok := matchDecimalPattern(message, "PREVIOUS_CHAT_IMPORT_ACTIVE_WAIT_", "MIN"); ok {
			return ErrPreviousChatImportActiveWaitMin, argument, true
		}
	case 'S':
		if argument, ok := matchDecimalPattern(message, "SESSION_TOO_FRESH_", ""); ok {
			return ErrSessionTooFresh, argument, true
		}
		if argument, ok := matchDecimalPattern(message, "SLOWMODE_WAIT_", ""); ok {
			return ErrSlowModeWait, argument, true
		}
		if argument, ok := matchDecimalPattern(message, "STARGIFT_RESELL_TOO_EARLY_", ""); ok {
			return ErrStarGiftResellTooEarly, argument, true
		}
		if argument, ok := matchDecimalPattern(message, "STARGIFT_TRANSFER_TOO_EARLY_", ""); ok {
			return ErrStarGiftTransferTooEarly, argument, true
		}
		if argument, ok := matchDecimalPattern(message, "STATS_MIGRATE_", ""); ok {
			return ErrStatsMigrate, argument, true
		}
		if argument, ok := matchDecimalPattern(message, "STORY_LIVE_ALREADY_", ""); ok {
			return ErrStoryLiveAlready, argument, true
		}
		if argument, ok := matchDecimalPattern(message, "STORY_SEND_FLOOD_MONTHLY_", ""); ok {
			return ErrStorySendFloodMonthly, argument, true
		}
		if argument, ok := matchDecimalPattern(message, "STORY_SEND_FLOOD_WEEKLY_", ""); ok {
			return ErrStorySendFloodWeekly, argument, true
		}
	case 'T':
		if argument, ok := matchDecimalPattern(message, "TAKEOUT_INIT_DELAY_", ""); ok {
			return ErrTakeoutInitDelay, argument, true
		}
	case 'U':
		if argument, ok := matchDecimalPattern(message, "USER_MIGRATE_", ""); ok {
			return ErrUserMigrate, argument, true
		}
	}
	return "", 0, false
}
